const assert = require('node:assert');


function test() {
  let candidate = do_algebra;
  assert.deepEqual(candidate(["**", "*", "+"], [2, 3, 4, 5]),37);
  assert.deepEqual(candidate(["+", "*", "-"], [2, 3, 4, 5]),9);
  assert.deepEqual(candidate(["//", "*"], [7, 3, 4]),8);
}

test();
